446cadaf115c206da4a143f3c58ef13b46d4a35a:
mutation SubmitClaim ($input: SubmitClaimInput!) {
  submitClaim(input: $input) {
    __typename
    ... on Claim {
      id
      status
      amount
    }
    ... on UserError {
      message
      path
    }
  }
}

